const output = [];

for (const item of $input.all()) {
  let text = item.json.text;

  // Skip empty values
  if (!text) {
    continue;
  }

  try {
    // If the LLM returned escaped JSON like:
    // {\n "Student_ID": "STU1001", ...}
    // convert it into normal JSON
    if (typeof text === 'string') {
      text = text.trim();

      // Remove markdown code fences if the LLM adds them
      text = text.replace(/^```json\s*/i, '');
      text = text.replace(/^```\s*/i, '');
      text = text.replace(/\s*```$/i, '');

      // Parse JSON string
      text = JSON.parse(text);
    }

    // Make sure we have an object
    if (text && typeof text === 'object' && !Array.isArray(text)) {
      output.push({
        json: {
          Student_ID: text.Student_ID ?? null,
          Name: text.Name ?? null,
          Email: text.Email ?? null,
          Phone: text.Phone ?? null,
          Course: text.Course ?? null,
          Fee_Paid: text.Fee_Paid ?? null,
          City: text.City ?? null,
          Enrolled_Date: text.Enrolled_Date ?? null,
          Email_Valid: text.Email_Valid ?? false
        }
      });
    }

  } catch (error) {
    // Keep invalid responses separate instead of breaking the workflow
    output.push({
      json: {
        error: true,
        message: 'Invalid JSON returned by LLM',
        raw_output: item.json.text
      }
    });
  }
}

return output;
